const items = {
    1: { id: 1, name: "Notebook" },
    2: { id: 2, name: "Mouse" },
    3: { id: 3, name: "Keyboard" }
};

msg.headers = { "Content-Type": "application/json; charset=utf-8" };

const rawId = msg.req.query.id;
if (rawId === undefined || rawId === null || rawId === "") {
    msg.statusCode = 400;
    msg.payload = { error: "Missing item id" };
    return msg;
}

const idText = String(rawId);
if (!/^[1-9]\d*$/.test(idText)) {
    msg.statusCode = 400;
    msg.payload = { error: "Invalid item id" };
    return msg;
}

const id = Number(idText);
if (!Number.isSafeInteger(id)) {
    msg.statusCode = 400;
    msg.payload = { error: "Invalid item id" };
    return msg;
}

if (!items[id]) {
    msg.statusCode = 404;
    msg.payload = { error: "Item not found" };
    return msg;
}

msg.statusCode = 200;
msg.payload = items[id];
return msg;
